for start_node in graph:
        if start_node in color:
            continue
        queue = deque([start_node])
        color[start_node] = 0
        while queue:
            node = queue.popleft()
            for neighbor in graph.get(node, []):
                if neighbor not in color:
                    color[neighbor] = 1 - color[node]
                    queue.append(neighbor)
                elif color[neighbor] == color[node]:
                    return False

